namespace ghidra.app.plugin.core.debug.gui.trace;

using static org.junit.Assert;



using org.junit;
using org.junit;

using ghidra.app.plugin.core.debug.gui;
using ghidra.app.plugin.core.debug.gui.listing;
using ghidra.trace.database;

public class DebuggerTraceTabPanelTest : AbstractGhidraHeadedDebuggerTest {
	private DebuggerTraceTabPanel traceTabs;

	/* @Before */
	public void setUpTabTest()
    {
		addPlugin(tool, typeof(DebuggerListingPlugin));
		DebuggerListingProvider listingProvider =
			waitForComponentProvider(typeof(DebuggerListingProvider));
		traceTabs = DebuggerListingProviderTestAccess.getTraceTabs(listingProvider);
	}

	/* @Test */
	public void testEmpty() {
		assertEquals(List.of(), traceTabs.getTabValues());
	}

	/* @Test */
	public void testOpenTraceAddsTab()
    {
		createAndOpenTrace();
		waitForSwing();

		assertEquals(List.of(tb.trace), traceTabs.getTabValues());
	}

	/* @Test */
	public void testActivateTraceSelectsTab()
    {
		using (ToyDBTraceBuilder tb1 = new ToyDBTraceBuilder(getName() + "_1", LANGID_TOYBE64))
using (ToyDBTraceBuilder tb2 = new ToyDBTraceBuilder(getName() + "_2", LANGID_TOYBE64))
{
			traceManager.openTrace(tb1.trace);
			traceManager.openTrace(tb2.trace);
			waitForSwing();

			traceManager.activateTrace(tb1.trace);
			waitForSwing();
			assertEquals(tb1.trace, traceTabs.getSelectedTabValue());

			traceManager.activateTrace(tb2.trace);
			waitForSwing();
			assertEquals(tb2.trace, traceTabs.getSelectedTabValue());
		}
	}

	/* @Test */
	public void testSelectTabActivatesTrace()
    {
		using (ToyDBTraceBuilder tb1 = new ToyDBTraceBuilder(getName() + "_1", LANGID_TOYBE64))
using (ToyDBTraceBuilder tb2 = new ToyDBTraceBuilder(getName() + "_2", LANGID_TOYBE64))
{
			traceManager.openTrace(tb1.trace);
			traceManager.openTrace(tb2.trace);
			waitForSwing();

			runSwing(() => traceTabs.selectTab(tb1.trace));
			waitForSwing();
			assertEquals(tb1.trace, traceManager.getCurrentTrace());

			runSwing(() => traceTabs.selectTab(tb2.trace));
			waitForSwing();
			assertEquals(tb2.trace, traceManager.getCurrentTrace());
		}
	}

	/* @Test */
	public void testCloseTraceRemovesTab()
    {
		using (ToyDBTraceBuilder tb1 = new ToyDBTraceBuilder(getName() + "_1", LANGID_TOYBE64))
using (ToyDBTraceBuilder tb2 = new ToyDBTraceBuilder(getName() + "_2", LANGID_TOYBE64))
{
			traceManager.openTrace(tb1.trace);
			traceManager.openTrace(tb2.trace);
			waitForSwing();

			assertEquals(List.of(tb1.trace, tb2.trace), traceTabs.getTabValues());

			traceManager.closeTrace(tb1.trace);
			waitForSwing();
			assertEquals(List.of(tb2.trace), traceTabs.getTabValues());

			traceManager.closeTrace(tb2.trace);
			waitForSwing();
			assertEquals(List.of(), traceTabs.getTabValues());
		}
	}
}
